import { sql } from "drizzle-orm";
import {
  boolean,
  char,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  unique,
  uuid,
  varchar,
} from "drizzle-orm/pg-core";
import { v7 as uuidv7 } from "uuid";
import { POST_KINDS } from "../../lib/posts";
import type { RichTextDocument } from "../../lib/rich-text";

// <-- Authentication -->
// Generated by Better Auth
export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").default(false).notNull(),
  image: text("image"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => /* @__PURE__ */ new Date())
    .notNull(),
});

export const session = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expires_at").notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [index("session_userId_idx").on(table.userId)],
);

export const account = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
  },
  (table) => [index("account_userId_idx").on(table.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
  },
  (table) => [index("verification_identifier_idx").on(table.identifier)],
);

// <-- Contact requests -->
/** Messages sent from the public contact form, after the Turnstile check. */
export const contactRequest = pgTable(
  "contact_requests",
  {
    id: uuid()
      .primaryKey()
      .$default(() => uuidv7()),
    firstName: varchar("first_name", { length: 255 }).notNull(),
    lastName: varchar("last_name", { length: 255 }).notNull(),
    email: varchar("email_address", { length: 255 }).notNull(),
    comment: text("comment").notNull(),
    /** They asked to join DQC's newsletters and future communications. */
    communicationsConsent: boolean("communications_consent").default(false),
    /**
     * Their Resend contact, made when they opted in. Null with consent means
     * adding them to Resend failed (see the server log), so it's still to do.
     */
    communicationsId: char("communications_id", { length: 36 }),
    /** When it was marked read in the admin; null while it's new. */
    readAt: timestamp("read_at"),
    createdAt: timestamp("created_at").notNull().default(sql`now()`),
  },
  (table) => [
    index("contact_request_read_at_created_at_idx").on(
      table.readAt,
      table.createdAt,
    ),
  ],
);
export type ContactRequest = typeof contactRequest.$inferSelect;
export type NewContactRequest = typeof contactRequest.$inferInsert;

// <-- Writing -->
/**
 * Thoughts (/thoughts) and statements (/statements), written in the admin
 * editor. The draft is saved separately from what's published, so content
 * edits stay private until "Publish". The details (title, slug, author,
 * summary) are live as soon as they're saved.
 */
export const post = pgTable(
  "post",
  {
    id: uuid("id")
      .primaryKey()
      .$default(() => uuidv7()),
    kind: text("kind", { enum: POST_KINDS }).notNull(),
    /** URL slug, unique within its kind: /thoughts/{slug} or /statements/{slug}. */
    slug: text("slug").notNull(),
    title: text("title").notNull(),
    /** Free text, e.g. "Devin Sharpe", or "Devin Sharpe and Laith Stevenson". */
    author: text("author"),
    /** Optional hand-written summary for lists and link previews. */
    description: text("description"),
    draftContent: jsonb("draft_content").$type<RichTextDocument>(),
    draftUpdatedAt: timestamp("draft_updated_at"),
    publishedContent: jsonb("published_content").$type<RichTextDocument>(),
    /** Opening text of the published content; the summary when there's no description. */
    excerpt: text("excerpt"),
    /** When the post went live. Set and cleared together with `publishedContent`. */
    publishedAt: timestamp("published_at"),
    /** When changes were last published to an already-live post. */
    revisedAt: timestamp("revised_at"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
  },
  (table) => [
    unique("post_kind_slug_unique").on(table.kind, table.slug),
    index("post_kind_published_at_idx").on(table.kind, table.publishedAt),
  ],
);
export type Post = typeof post.$inferSelect;
export type NewPost = typeof post.$inferInsert;

// <-- Projects -->
export const project = pgTable("project", {
  /** URL slug: /projects/{id}. */
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  description: text("description"),
  /** The project's own site, or the organization it was for. */
  websiteLink: text("website_link"),
  sourceLink: text("source_link"),
  /** Free-form display dates, e.g. "Spring 2026". */
  startDate: text("start_date").notNull(),
  endDate: text("end_date"),
  /** Active and past projects are listed (and ordered) separately. */
  isActive: boolean("is_active").notNull().default(true),
  sortOrder: integer("sort_order").notNull().default(0),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => /* @__PURE__ */ new Date())
    .notNull(),
});
export type Project = typeof project.$inferSelect;
export type NewProject = typeof project.$inferInsert;

/**
 * A project's page (/projects/{id}), written in the admin editor. As with
 * posts, the draft is saved separately and goes live on "Publish".
 */
export const projectPage = pgTable("project_page", {
  projectId: text("project_id")
    .primaryKey()
    .references(() => project.id, { onDelete: "cascade", onUpdate: "cascade" }),
  draftContent: jsonb("draft_content").$type<RichTextDocument>(),
  draftUpdatedAt: timestamp("draft_updated_at"),
  publishedContent: jsonb("published_content").$type<RichTextDocument>(),
  publishedAt: timestamp("published_at"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => /* @__PURE__ */ new Date())
    .notNull(),
});
export type ProjectPage = typeof projectPage.$inferSelect;

// <-- Team -->
/**
 * The people under "Our Team" on /about, in `sort_order`. Someone is listed
 * once their bio is published; name and pronouns are live as soon as they're
 * saved.
 */
export const teamMember = pgTable("team_member", {
  id: uuid("id")
    .primaryKey()
    .$default(() => uuidv7()),
  name: text("name").notNull(),
  pronouns: text("pronouns"),
  draftContent: jsonb("draft_content").$type<RichTextDocument>(),
  draftUpdatedAt: timestamp("draft_updated_at"),
  publishedContent: jsonb("published_content").$type<RichTextDocument>(),
  publishedAt: timestamp("published_at"),
  sortOrder: integer("sort_order").notNull().default(0),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => /* @__PURE__ */ new Date())
    .notNull(),
});
export type TeamMember = typeof teamMember.$inferSelect;

// <-- Relations -->
export const schema = {
  user,
  session,
  account,
  verification,
  contactRequest,
  post,
  project,
  projectPage,
  teamMember,
} as const;
